Object.assign(SNIP,{});PRESET_NOTES["l4"]={"Ví dụ: Tràn khi nhân hai số int": "a * b tính bằng int nên tràn trước khi gán vào long long. 1LL * a * b đổi phép tính sang long long ngay từ đầu.", "Ví dụ: Tổng dãy cần long long": "Ba số đều vừa int nhưng tổng 3·10⁹ thì không. s1 (int) quay vòng thành số âm, s2 (long long) đúng.", "Ví dụ: Chia và chia dư với số âm": "−7 / 3 = −2 (làm tròn về 0), −7 % 3 = −1. Cách đưa số dư về 0..m−1 cho 2. Dòng cuối: a % 2 == 1 sai với số lẻ âm, a % 2 != 0 thì đúng.", "Ví dụ: Lũy thừa lấy dư 10^9 + 7": "2¹⁰⁰ lớn hơn nhiều so với long long, nhưng lấy dư sau mỗi lần nhân thì p luôn nhỏ hơn MOD, và p * 2 không bao giờ tràn."};EX_HINTS["l4"]=[["Code mẫu đúng ý nhưng sai kiểu: tổng vượt int."], ["n·(n−1) với n = 10⁶ là khoảng 10¹² > 2,1·10⁹.", "Chia 2 sau khi nhân vẫn đúng vì n·(n−1) luôn chẵn."], ["Trong C++, a % m âm khi a âm.", "Cộng thêm m rồi lấy dư lần nữa: ((a % m) + m) % m."]];
