const PR4=[{label:"Ví dụ: Tràn khi nhân hai số int",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int a = 100000, b = 100000;\n    long long sai = a * b;\n    long long dung = 1LL * a * b;\n    cout << sai << \"\\n\" << dung << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","sai","dung"]}]},{label:"Ví dụ: Tổng dãy cần long long",input:"3\n1000000000 1000000000 1000000000",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"TONG.INP\", \"r\")) {\n        freopen(\"TONG.INP\", \"r\", stdin);\n        freopen(\"TONG.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    int s1 = 0;\n    long long s2 = 0;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        s1 += x;\n        s2 += x;\n    }\n    cout << s1 << \"\\n\" << s2 << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["x","s1","s2"]}]},{label:"Ví dụ: Chia và chia dư với số âm",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int a = -7, m = 3;\n    cout << a / m << \" \" << a % m << \"\\n\";\n    cout << ((a % m) + m) % m << \"\\n\";\n    cout << (a % 2 == 1) << \" \" << (a % 2 != 0) << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Lũy thừa lấy dư 10^9 + 7",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    const long long MOD = 1000000007;\n    long long p = 1;\n    for (int i = 1; i <= 100; i++) {\n        p = p * 2 % MOD;\n    }\n    cout << p << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["i","p"]}]}];
